import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState, AppDispatch } from '../../store/store';
import { fetchTemporalAnalysis, fetchAccountCorrelation } from '../../store/slices/analyticsSlice';
import './Analytics.css';

const Analytics: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { 
    temporalAnalysis, 
    correlationData,
    isLoadingTemporal,
    isLoadingCorrelation,
    temporalError,
    correlationError
  } = useSelector((state: RootState) => state.analytics);

  useEffect(() => {
    // Fetch temporal patterns for a default account
    dispatch(fetchTemporalPatterns({ 
      account: 'IPS_TM_10', 
      analysisType: 'hour' 
    }));
    dispatch(fetchAccountComparisons());
  }, [dispatch]);

  if (isLoading) {
    return (
      <div className="analytics">
        <div className="loading">Loading analytics data...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="analytics">
        <div className="error">Error loading analytics: {error}</div>
      </div>
    );
  }

  return (
    <div className="analytics">
      <h1>Trading Analytics</h1>
      
      <div className="analytics-grid">
        <div className="analytics-card">
          <h3>Temporal Patterns</h3>
          <div className="temporal-section">
            <h4>Trading Patterns by Hour</h4>
            <div className="pattern-list">
              {temporalPatterns?.length ? (
                temporalPatterns.map((pattern, index) => (
                  <div key={index} className="pattern-item">
                    <span>Hour {pattern.hourOfDay}:00</span>
                    <span>{pattern.winRate?.toFixed(1)}% win rate</span>
                    <span>{pattern.totalTrades} trades</span>
                  </div>
                ))
              ) : (
                <div className="no-data">No temporal data available</div>
              )}
            </div>
          </div>
        </div>

        <div className="analytics-card">
          <h3>Account Comparisons</h3>
          <div className="comparison-table">
            {accountComparisons?.length ? (
              accountComparisons.map((comparison, index) => (
                <div key={index} className="comparison-item">
                  <div className="comparison-header">
                    <span>{comparison.account1} vs {comparison.account2}</span>
                  </div>
                  <div className="comparison-metrics">
                    <span>Performance Difference: {comparison.performanceDifference?.toFixed(2)}%</span>
                    <span>Statistical Significance: {comparison.statisticalSignificance?.toFixed(3)}</span>
                  </div>
                </div>
              ))
            ) : (
              <div className="no-data">No comparison data available</div>
            )}
          </div>
        </div>

        <div className="analytics-card full-width">
          <h3>Performance Overview</h3>
          <div className="overview-placeholder">
            <p>Detailed performance charts and analysis will be displayed here.</p>
            <p>This section will include:</p>
            <ul>
              <li>Performance trends over time</li>
              <li>Risk-adjusted returns</li>
              <li>Drawdown analysis</li>
              <li>Correlation matrices</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;
